/* Minimal magnetic dot. One sleeping RAF loop, cached target geometry. */
(()=>{const html=document.documentElement,eligible=matchMedia('(hover:hover) and (pointer:fine) and (min-width:1025px)'),reduced=matchMedia('(prefers-reduced-motion:reduce)');
const layer=document.createElement('div');layer.className='premium-cursor-layer';layer.dataset.state='default';layer.setAttribute('aria-hidden','true');layer.innerHTML='<span class="premium-cursor-dot"><span class="magnetic-dot-core"></span></span>';document.body.append(layer);const dot=layer.firstElementChild;
const interactive='a[href],button:not(:disabled),summary,[role="button"],[role="tab"],.tech,.work-slide',important='#accueil .hero-cta-row .button,#cv .cv-actions .button,.header .nav-cv,#projects .open-project',native='input,textarea,select,iframe,object,embed,dialog,[contenteditable="true"]';
let enabled=false,shown=false,frame=0,last=0,x=0,y=0,px=0,py=0,tx=0,ty=0,attracted=null,rect=null,magnet=null,card=null,hitTest=false;const returns=new Set(),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function release(immediate=false){if(!magnet)return;const m=magnet;magnet=null;if(!immediate&&enabled&&!reduced.matches){const a=m.el.animate([{translate:`${m.x}px ${m.y}px`},{translate:m.base||'0px 0px'}],{duration:300,easing:'cubic-bezier(.22,1,.36,1)'});returns.add(a);a.finished.then(()=>returns.delete(a),()=>returns.delete(a))}if(m.baseInline)m.el.style.translate=m.baseInline;else m.el.style.removeProperty('translate')}
function clearCard(){card?.classList.remove('magnetic-dot-card-hover');card=null}
function hide(){shown=false;layer.classList.remove('is-visible');cancelAnimationFrame(frame);frame=0;last=0;release(true);clearCard();attracted=rect=null}
function configure(){enabled=eligible.matches&&navigator.maxTouchPoints===0&&!reduced.matches;html.classList.toggle('premium-cursor-enabled',enabled);returns.forEach(a=>a.cancel());returns.clear();hide()}
function context(target){if(!(target instanceof Element)||target.closest(native)){hide();return false}const next=target.closest(interactive);if(next!==attracted){attracted=next;rect=next?.getBoundingClientRect()||null;layer.dataset.state=next?'interactive':'default'}
const hoveredCard=target.closest('.work-slide');if(hoveredCard!==card){clearCard();card=hoveredCard;card?.classList.add('magnetic-dot-card-hover')}
const button=target.closest(important);if(button!==magnet?.el){release();if(button){const r=button===next?rect:button.getBoundingClientRect(),base=getComputedStyle(button).translate;const p=base.split(' ');magnet={el:button,r,base:base==='none'?'0px 0px':base,baseInline:button.style.translate,x:0,y:parseFloat(p[1])||0,tx:0,ty:0,baseY:parseFloat(p[1])||0}}}return true}
function aim(){tx=x;ty=y;if(rect){tx+=clamp((rect.left+rect.width/2-x)*.12,-6,6);ty+=clamp((rect.top+rect.height/2-y)*.12,-6,6)}if(magnet){const m=magnet,r=m.r;m.tx=clamp(((x-r.left)/r.width-.5)*8,-4,4);m.ty=clamp(((y-r.top)/r.height-.5)*8+m.baseY,-4,4)}}
function schedule(){if(!frame&&enabled&&shown&&!document.hidden)frame=requestAnimationFrame(tick)}
function tick(now){frame=0;if(!enabled||!shown||document.hidden)return;if(hitTest){hitTest=false;if(!context(document.elementFromPoint(x,y)))return;aim()}const dt=Math.min(40,last?now-last:16);last=now;const smooth=1-Math.exp(-dt/18);px+=(tx-px)*smooth;py+=(ty-py)*smooth;dot.style.transform=`translate3d(${px.toFixed(2)}px,${py.toFixed(2)}px,0)`;let moving=Math.abs(tx-px)+Math.abs(ty-py)>.04;
if(magnet){const m=magnet,ease=1-Math.exp(-dt/45);m.x+=(m.tx-m.x)*ease;m.y+=(m.ty-m.y)*ease;m.el.style.translate=`${m.x.toFixed(2)}px ${m.y.toFixed(2)}px`;moving=moving||Math.abs(m.tx-m.x)+Math.abs(m.ty-m.y)>.02}if(moving)frame=requestAnimationFrame(tick);else last=0}
document.addEventListener('pointermove',e=>{if(!enabled||e.pointerType!=='mouse')return;x=e.clientX;y=e.clientY;if(!context(e.target))return;aim();if(!shown){px=tx;py=ty;shown=true;layer.classList.add('is-visible')}schedule()},{passive:true});document.addEventListener('pointerover',e=>{if(enabled&&e.pointerType==='mouse'&&context(e.target)){aim();schedule()}},{passive:true});
document.documentElement.addEventListener('pointerleave',hide);addEventListener('blur',hide);document.addEventListener('keydown',e=>{if(e.key==='Tab')hide()});document.addEventListener('visibilitychange',()=>{if(document.hidden)hide()});addEventListener('scroll',()=>{if(!enabled||!shown)return;release(true);attracted=rect=null;hitTest=true;schedule()},{passive:true});addEventListener('resize',()=>{hide()},{passive:true});eligible.addEventListener('change',configure);reduced.addEventListener('change',configure);configure();
})();
